INSERT INTO File(media_id, mrl, type, last_modification_date, size, folder_id, is_removable, is_external, is_network) VALUES(2, 'file:///storage/emulated/0/VLCVideos/scene_68_4K_copy.mp4', 0, 1697384150, 1391881, 1, 0, 0, 0);

